// src/pages/AdminDashboard.js
import React from 'react';
import { useNavigate } from 'react-router-dom';
import { logout } from '../services/api'; // Adjust the path to your actual location

const AdminDashboard = () => {
  const navigate = useNavigate();

  // Handle logout logic
  const handleLogout = async () => {
    try {
      // Call the logout function from api.js and pass navigate for redirection
      await logout(navigate); // logout will now handle the token removal and redirection

      // Optional: you can also remove the token from localStorage manually (just to be thorough)
      localStorage.removeItem('token');

      // You can log out or show a message if you want here
      // Redirect will be handled in logout() function
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  return (
    <div>
      <h1>Admin Dashboard</h1>
      <button onClick={() => navigate('/create-user')}>Create User</button>
      <button onClick={() => navigate('/exam-data')}>Manage Exam Data</button>
      
      {/* Logout button */}
      <button onClick={handleLogout}>Logout</button>
    </div>
  );
};

export default AdminDashboard;
